<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$id=trim($_GET['identifier']??'');if(!$id)fail('Identifier is required.');$s=db()->prepare('SELECT s.*,p.name,p.unique_identifier,u.full_name seller_name,u.shop_name,u.phone seller_phone FROM sales s JOIN products p ON p.id=s.product_id JOIN users u ON u.id=s.seller_id WHERE p.unique_identifier=? AND s.seller_id=? AND s.id NOT IN(SELECT sale_id FROM returns) ORDER BY s.sold_at DESC LIMIT 1');$s->execute([$id,$u['id']]);$sale=$s->fetch();if(!$sale)fail('Sale not found or already returned.',404);$sale['warranty_status']=!(int)$sale['warranty_months']||empty($sale['warranty_ends_at'])?'no_warranty':($sale['warranty_ends_at']>=date('Y-m-d')?'valid':'expired');$sale['can_return']=$sale['warranty_status']==='valid';out(['success'=>true,'sale'=>$sale]);
